  "codebook": {
    "definition": "Credit-claiming refers to statements in which a senator asserts personal or direct responsibility for securing a desirable government action, such as federal funding, local grants, specific facilities, or the successful passage of specific legislation or amendments that benefit their constituents or advance a specific policy goal.",
    "clarification": "A text should be classified as credit-claiming if the senator announces the receipt of a federal grant or award by their state (acting as the messenger of good news), explicitly points to their own legislative work that has been passed or adopted (e.g., 'my amendment was adopted', 'legislation I authored was passed'), or highlights their successful intervention with a federal agency to secure a specific benefit or decision.",
    "positive_examples": [
      {
        "text": "Senator Smith today announced that the Department of Homeland Security will release $100,000 to the local Fire Department. 'I am pleased to help secure these vital funds for our first responders,' Smith said.",
        "explanation": "This text is credit-claiming because the senator is announcing a federal grant awarded to their state and explicitly claims responsibility for helping to secure the funding."
      },
      {
        "text": "The Senate today overwhelmingly passed the defense bill, which includes an amendment authored by Senator Jones to protect local military bases from closure.",
        "explanation": "This text is credit-claiming because the senator highlights the successful passage of an amendment that they authored, explicitly connecting their legislative work to a desirable outcome."
      },
      {
        "text": "Following an appeal from Senator Doe last week, the USDA has announced it will expedite disaster relief to local farmers.",
        "explanation": "This text is credit-claiming because it draws a direct causal link between the senator's advocacy (the appeal) and the agency's favorable policy decision."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming if the senator is merely expressing an opinion (position-taking), introducing a bill that has not yet passed, voting for a broad piece of legislation without claiming authorship of its provisions, or advocating for a future action without announcing a concrete success.",
    "negative_examples": [
      {
        "text": "Senator Johnson today introduced legislation that would expand access to renewable energy. 'We must do more to protect our environment,' Johnson said.",
        "explanation": "This is not credit-claiming because the senator is merely announcing the introduction of a bill. They have not yet secured its passage or delivered a concrete benefit."
      },
      {
        "text": "I was proud to vote for the comprehensive tax reform package today because it will help working families in our state.",
        "explanation": "This is not credit-claiming because the senator is simply explaining their vote on a general piece of legislation, without asserting personal responsibility for authoring or securing specific provisions."
      },
      {
        "text": "Senator Miller sent a letter to the EPA today urging them to reconsider their recent regulations on agricultural runoff.",
        "explanation": "This is not credit-claiming because it represents advocacy and oversight. The senator has not yet achieved a reversal of the policy."
      }
    ]
  }
}
